// Declarar un array de 5 enteros (todos inician en 0)
int[] puntos = new int[5];

// Inicializar con valores
string[] nombres = new string[] { "Ana", "Luis", "Mia" };

// Acceder por índice (¡los índices empiezan en 0!)
Debug.Log(nombres[0]); // "Ana"
Debug.Log(nombres[1]); // "Luis"
Debug.Log(nombres[2]); // "Mia"

// Modificar un elemento
puntos[0] = 100;
puntos[4] = 50; // último elemento de un array de tamaño 5

// Recorrer con for
for (int i = 0; i < puntos.Length; i++)
{
    Debug.Log("Punto " + i + ": " + puntos[i]);
}

// Array multidimensional (tabla 3x3)
int[,] tablero = new int[3, 3];
tablero[0, 0] = 1;
tablero[2, 2] = 9;

